Let's refine the `resolveBrickCollision` logic.

```javascript
function resolveBrickCollision(ball, brick) {
  const dx = ball.x - (brick.x + brick.w / 2);
  const dy = ball.y - (brick.y + brick.h / 2);
  const width = brick.w / 2 + ball.r;
  const height = brick.h / 2 + ball.r;

  const crossW = width * dy;
  const crossH = height * dx;

  if (Math.abs(dx) <= width && Math.abs(dy) <= height) {
    if (crossW > crossH) {
      if (crossW > -crossH) {
        // Bottom
        ball.y = brick.y + brick.h + ball.r;
        ball.vy = Math.abs(ball.vy) * DOWN;
      } else {
        // Left
        ball.x = brick.x - ball.r;
        ball.vx = Math.abs(ball.vx) * LEFT;
      }
    } else {
      if (crossW > -crossH) {
        // Right
        ball.x = brick.x + brick.w + ball.r;
        ball.vx = Math.abs(ball.vx) * RIGHT;
      } else {
        // Top
        ball.y = brick.y - ball.r;
        ball.vy = Math.abs(ball.vy) * UP;
      }
    }
  }
}
```
