function resolveBrickCollision(ball, brick) {
  console.log('Resolving collision:', { ball, brick });
  const overlapX = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
  const overlapY = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));
  console.log('Overlaps:', { overlapX, overlapY });

  if (Math.abs(overlapX - overlapY) < 0.1) {
    // Corner hit: reflect both axes
    ball.vx = (ball.x < brick.x + brick.w / 2) ? Math.abs(ball.vx) * LEFT : Math.abs(ball.vx) * RIGHT;
    ball.vy = (ball.y < brick.y + brick.h / 2) ? Math.abs(ball.vy) * UP : Math.abs(ball.vy) * DOWN;
    ball.x = (ball.x < brick.x + brick.w / 2) ? brick.x - ball.r : brick.x + brick.w + ball.r;
    ball.y = (ball.y < brick.y + brick.h / 2) ? brick.y - ball.r : brick.y + brick.h + ball.r;
  } else if (overlapX < overlapY) {
    // Horizontal collision
    if (ball.x < brick.x + brick.w / 2) {
      ball.x = brick.x - ball.r;
      ball.vx = Math.abs(ball.vx) * LEFT;
    } else {
      ball.x = brick.x + brick.w + ball.r;
      ball.vx = Math.abs(ball.vx) * RIGHT;
    }
  } else {
    // Vertical collision
    if (ball.y < brick.y + brick.h / 2) {
      ball.y = brick.y - ball.r;
      ball.vy = Math.abs(ball.vy) * UP;
    } else {
      ball.y = brick.y + brick.h + ball.r;
      ball.vy = Math.abs(ball.vy) * DOWN;
    }
  }
}

